<script lang="ts">
 import SampleSpecImport from './SampleSpecImport.svelte';
 import {api} from './api';
 let {piece,data,onchange,onprint,onissue}:{piece:any;data:any;onchange:()=>Promise<void>;onprint:(kind:string,id:number)=>void;onissue:()=>void}=$props();
 let busy=$state(false),error=$state(''),editor=$state(''),values:any=$state({}),note=$state(''),audit:any=$state(null);
 const fields=[['pattern_by','Pattern by'],['cut_by','Cut by'],['sample_maker','Sample tailor / maker'],['pattern_plan_date','Pattern plan','date'],['cutting_plan_date','Cutting plan','date'],['allocation_plan_date','Tailor allocation plan','date'],['sewing_plan_date','Sewing completion plan','date'],['finishing_plan_date','Finishing plan','date'],['audit_plan_date','Audit plan','date'],['handover_plan_date','Final handover plan','date'],['fabric_expected_date','Fabric expected','date'],['trims_expected_date','Trims expected','date'],['fabric_update_date','Fabric ready','date'],['trims_update_date','Trims ready','date'],['style_update_date','Style ready','date'],['readiness_note','Readiness remarks'],['handover_dc','Handover DC'],['enclosures','Enclosures']];
 const transitions=[['cut','Pattern ready','Cutting completed'],['allocate','Cut','Allocate to sample tailor'],['sew_start','Allocated','Start sewing'],['sew_start','Rework','Start rework'],['sew','Sewing','Sewing completed'],['finish_start','Sewn','Start finishing'],['finish','Finishing','Finishing completed → QA']];
 const title=(k:string)=>fields.find(f=>f[0]===k)?.[1]||k.replaceAll('_',' ');
 async function action(action:string,extra:any={}){if(busy)return;busy=true;error='';try{await api('/sample-indents/'+piece.id,{version:piece.version,action,...extra});editor='';await onchange()}catch(e){error=(e as Error).message}finally{busy=false}}
 function startAudit(){const previous=piece.production.audit_reports?.at(-1);audit={fabric_used:'Actual',trims_used:'Actual',style_used:'Actual',submission_attempt:String(Math.min(4,(previous?Number(previous.submission_attempt):0)+1)),special_remarks:'',merchant_contact:'',measurements:previous?structuredClone($state.snapshot(previous.measurements)):[]};note='';editor='audit'}
</script>
<article class="piece"><header><div><h3>#{piece.id} · {piece.size} · {piece.colour}</h3><strong>{piece.status}</strong></div><div class="actions"><button class="button secondary" onclick={()=>onprint('indent',piece.id)}>Print indent</button>{#if piece.production.audit_reports?.length}<button class="button secondary" onclick={()=>onprint('audit',piece.id)}>Print audit reports</button>{/if}{#if piece.status==='Handed over'}<button class="button secondary" onclick={()=>onprint('dispatch',piece.id)}>Print dispatch label</button>{/if}</div></header>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}
 <details><summary>Plan, readiness and completed milestones</summary><dl>{#each Object.entries(piece.production).filter(([k,v])=>v&&k!=='audit_reports') as [key,value]}<div><dt>{title(key)}</dt><dd>{String(value)}</dd></div>{/each}</dl></details>
 <div class="actions">
 {#if data.can_produce&&!['Handed over','Rejected'].includes(piece.status)}<button class="button secondary" disabled={busy} onclick={()=>{values={...piece.production};editor='plan'}}>Plan / readiness</button><button class="button secondary" disabled={busy} onclick={()=>{note=piece.production.file_review_note||'';editor='file'}}>Review sample file</button>{/if}
 {#if data.can_stock&&!['Handed over','Rejected'].includes(piece.status)}<button class="button secondary" disabled={busy} onclick={onissue}>Issue fabric</button>{/if}
 {#if data.can_pattern&&piece.status==='Ready'}<button class="button primary" disabled={busy} onclick={()=>action('pattern')}>Pattern completed</button>{/if}
 {#if data.can_produce}{#each transitions.filter(t=>t[1]===piece.status) as [key,,label]}<button class="button primary" disabled={busy} onclick={()=>action(key)}>{label}</button>{/each}{/if}
 {#if data.can_audit&&['Awaiting audit','Audit'].includes(piece.status)}{#if piece.status==='Awaiting audit'}<button class="button secondary" disabled={busy} onclick={()=>action('audit_start')}>Start audit</button>{/if}<button class="button primary" disabled={busy} onclick={startAudit}>Complete audit report</button>{/if}
 {#if data.can_handover&&piece.status==='Approved'}<button class="button primary" disabled={busy} onclick={()=>action('merchant_handover',{destination:'Merchant'})}>Handover to merchant</button><button class="button secondary" disabled={busy} onclick={()=>action('merchant_handover',{destination:'Showroom'})}>Handover to showroom</button>{/if}
 {#if data.can_handover&&['With merchant','Showroom'].includes(piece.status)}<button class="button primary" disabled={busy} onclick={()=>{values={...piece.production};editor='dispatch'}}>Final customer handover</button>{/if}
 {#if data.can_feedback&&piece.status==='Handed over'}<button class="button secondary" onclick={()=>{note=piece.production.buyer_comments||'';editor='feedback'}}>Buyer pass / fail / comments</button>{/if}
 </div>
 {#if editor==='file'||editor==='feedback'}<section class="editor"><h3>{editor==='file'?'Sample file clearance':'Buyer feedback'}</h3><label>Remarks / missing items<textarea bind:value={note} maxlength="2000"></textarea></label><footer>{#each editor==='file'?['Clear','Missing']:['Pass','Fail','Comments'] as result}<button class="button secondary" disabled={busy} onclick={()=>action(editor==='file'?'file_review':'buyer_feedback',{result,note})}>{result}</button>{/each}<button class="text-button" onclick={()=>editor=''}>Cancel</button></footer></section>{/if}
 {#if editor==='plan'}<section class="editor"><h3>Plan · Indent #{piece.id}</h3><div class="grid">{#each fields as [key,label,type]}<label>{label}<input type={type==='date'?'date':'text'} bind:value={values[key]} maxlength="2000"/></label>{/each}</div><footer><button class="button primary" disabled={busy} onclick={()=>action('plan',{production:values})}>Save plan</button><button class="button secondary" disabled={busy} onclick={()=>editor=''}>Cancel</button></footer></section>{/if}
 {#if editor==='audit'}<section class="editor"><h3>Audit report · Indent #{piece.id}</h3><p>Compare the required specification with the measured garment. Your account and submission time sign this report. Earlier reports remain in history.</p><div class="grid">{#each [['fabric_used','Fabric'],['trims_used','Trims'],['style_used','Style']] as [key,label]}<label>{label}<select bind:value={audit[key]}><option>Actual</option><option>Alternate</option></select></label>{/each}<label>Submission attempt<select bind:value={audit.submission_attempt}>{#each ['1','2','3','4'] as n}<option>{n}</option>{/each}</select></label><label>Special remarks<textarea bind:value={audit.special_remarks}></textarea></label><label>Merchant contact<input bind:value={audit.merchant_contact}/></label></div><h4>Measurements</h4><SampleSpecImport indent={piece.id} onsave={rows=>audit.measurements=rows}/>
 {#if !audit.measurements.length}<p>Add measurement points from the buyer specification.</p>{/if}
 {#each audit.measurements as row,i}<div class="measurement"><label>Measurement point<input bind:value={row.point}/></label><label>Required<input type="number" step="any" min="0" bind:value={row.required}/></label><label>Actual<input type="number" step="any" min="0" bind:value={row.actual}/></label><label>Unit<select bind:value={row.unit}><option>cm</option><option>mm</option><option>in</option></select></label><label>Tolerance ± (optional)<input type="number" step="any" min="0" bind:value={row.tolerance}/></label><label>Remarks<input bind:value={row.remarks}/></label><button class="text-button" onclick={()=>audit.measurements.splice(i,1)}>Remove</button></div>{/each}
 <button class="button secondary" disabled={audit.measurements.length>=100} onclick={()=>audit.measurements.push({point:'',required:'',actual:'',unit:'cm',tolerance:'',remarks:''})}>Add measurement</button><label class="remarks">QA decision remarks<textarea bind:value={note}></textarea></label><p>Upload the fabric swatch, trim card or audit attachment under Documents and select indent #{piece.id}.</p><footer>{#each ['Approved','Rework','Rejected'] as result}<button class="button secondary" disabled={busy||!audit.measurements.length||(result!=='Approved'&&!note.trim())} onclick={()=>action('audit',{result,note,audit})}>{result==='Approved'?'Approve to send':result}</button>{/each}<button class="text-button" disabled={busy} onclick={()=>editor=''}>Cancel</button></footer></section>{/if}
 {#if editor==='dispatch'}<section class="editor"><h3>Final customer handover · #{piece.id}</h3><div class="grid"><label>AWB / shipment or delivery reference<input bind:value={values.awb}/></label><label>Contact<input bind:value={values.dispatch_contact}/></label><label>To — customer name and full address<textarea rows="4" bind:value={values.dispatch_to}></textarea></label><label>From — sender name and full address<textarea rows="4" bind:value={values.dispatch_from}></textarea></label></div><p>Confirm only once the sample has been handed over for the customer. This closes the indent and records your name and time.</p><footer><button class="button primary" disabled={busy||!values.awb?.trim()||!values.dispatch_to?.trim()||!values.dispatch_from?.trim()} onclick={()=>action('handover',{dispatch:values})}>Confirm final handover</button><button class="button secondary" disabled={busy} onclick={()=>editor=''}>Cancel</button></footer></section>{/if}
 {#if piece.production.audit_reports?.length}<details><summary>Signed audit reports ({piece.production.audit_reports.length})</summary>{#each piece.production.audit_reports as report}<div class="audit-summary"><strong>Revision {report.revision} · {report.result}</strong><p>{report.auditor} · {new Date(report.signed_at).toLocaleString()} · Submission {report.submission_attempt}</p><div class="scroll"><table><thead><tr><th>Measurement</th><th>Required</th><th>Actual</th><th>Tolerance ±</th><th>Remarks</th></tr></thead><tbody>{#each report.measurements as m}<tr><td>{m.point}</td><td>{m.required} {m.unit}</td><td>{m.actual} {m.unit}</td><td>{m.tolerance||'—'}</td><td>{m.remarks}</td></tr>{/each}</tbody></table></div><p>{report.remarks} {report.special_remarks}</p></div>{/each}</details>{/if}
</article>
<style>
 .piece{border:1px solid #b4c7c1;background:#f8faf9;padding:18px;border-radius:10px;margin:18px 0}.piece header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}h3{margin:4px 0 12px}p{line-height:1.55}.actions,footer{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:16px 0}label{display:grid;gap:7px;color:#10202b;font-weight:700}input,select,textarea{width:100%;min-width:0;min-height:42px;padding:10px;border:1px solid #aebfc9;border-radius:7px;background:#eff5fa;color:#101820;font-size:14px;font-weight:600}textarea{resize:vertical}.grid,dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}dt{font-weight:700;text-transform:capitalize}dd{margin:5px 0;overflow-wrap:anywhere}.editor{margin-top:20px;background:#edf4f7;border:1px solid #b5c8d1;padding:18px;border-radius:10px}.measurement{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:10px;margin:14px 0;padding-bottom:16px;border-bottom:1px solid #b9cbd4}.measurement label:last-of-type{grid-column:1/5}.remarks{margin-top:20px}summary{cursor:pointer;font-weight:700;margin:16px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #c9d5da}.audit-summary{padding:15px;border:1px solid #c9d5da;border-radius:8px;margin:12px 0}@media(max-width:700px){.grid,dl{grid-template-columns:1fr}.measurement{grid-template-columns:1fr 1fr}.measurement label:first-child,.measurement label:last-of-type{grid-column:1/-1}}
</style>
